export type PascaCategoryId =
  | "pln" | "pdam" | "pbb" | "internet" | "tv" | "hp"
  | "bpjs" | "multifinance" | "gas";

export interface PascaCategoryInfo {
  id: PascaCategoryId;
  label: string;
  desc: string;
  targetLabel: string;
  /** Kolom kedua (PBB: kode pembayaran + nomor identitas, digabung koma). */
  secondLabel?: string;
}

export interface PascaProduct {
  /** buyer_sku_code Digiflazz. */
  sku: string;
  /** Nama produk tampilan (mis. "PDAM Aetra"). */
  name: string;
  /** Brand Digiflazz asli (mis. "PDAM"). */
  brand: string;
  category: PascaCategoryId;
  /** Biaya admin dibayar pembeli (Rp). */
  admin: number;
  /** Komisi toko dari Digiflazz (Rp) — internal, tidak tampil ke pembeli. */
  commission: number;
  /** Deskripsi (wilayah/tipe). */
  desc: string;
}

